// Zero-loss check: source and destination checksums must match exactly
const src=["r1:a", "r2:b", "r3:c"],dst=["r1:a", "r2:b", "r3:c"];
const sum=a=>a.map(r=>{let h=0;for(const ch of r)h=(h*31+ch.charCodeAt(0))>>>0;return h;});
const A=sum(src),B=sum(dst);
const ok=A.length===B.length&&A.every((v,i)=>v===B[i]);
console.log('rows:',A.length,'| checksums match:',ok,'| zero-loss:',ok);

